        public MainWindow()
        {
            // Nur eine Instanz: ein zweiter Start holt das bereits laufende Fenster nach vorn
            if (!AcquireSingleInstance()) Environment.Exit(0);

            ApplyRenderModeEarly();
            InitializeComponent();
            LoadSettings();
            InitLanguage();
            RestoreWindowBounds();
            InitSystemMonitoring();
            ApplyViewSettings();

            BuildToolTiles();
            BuildLinkTiles();
            RefreshApps();
            ApplyTileNames(ReadGpuAdapters());

            // Änderungen an Reglern werden gesammelt angewendet
            applyTimer.Interval = TimeSpan.FromMilliseconds(350);
            applyTimer.Tick += (s, e) =>
            {
                applyTimer.Stop();
                SaveSettings();
                ApplyViewSettings();
                ApplyFilter();
                RefreshDashboard();
            };

            clockTimer.Interval = TimeSpan.FromSeconds(1);
            clockTimer.Tick += (s, e) => UpdateClock();
            clockTimer.Start();

            weatherTimer.Interval = TimeSpan.FromMinutes(20);
            weatherTimer.Tick += async (s, e) => await RefreshWeatherAsync();
            weatherTimer.Start();

            InitFeatures();
            InitExtras();
            InitComfort();
            InitExtras3();
            InitExtras4();
            InitExtras5();
            InitExtras6();
            InitExtras7();
            InitExtras8();
            InitExtras9();
            InitExtras10();
            InitExtras11();
            InitExtras12();
            InitExtras13();
            InitExtras14();
            InitExtras15();
            InitExtras16();
            InitExtras17();
            InitExtras18();
            InitExtras19();
            InitExtras20();
            InitExtras21();

            isLoadingSettings = false;
            RefreshDashboard();
            UpdateClock();
            ShowStartPage();

            Loaded += async (s, e) =>
            {
                _ = RefreshWeatherAsync();
                _ = RefreshHardwareAsync();
                await LoadInstalledGamesAsync();
            };
            Closing += (s, e) => SaveWindowBounds();
            Closed += (s, e) => DisposeMonitoring();
        }

