        private void InitExtras()
        {
            AllowDrop = true;
            DragOver += OnWindowDragOver;
            Drop += OnWindowDrop;

            maintenanceTimer.Interval = TimeSpan.FromMinutes(30);
            maintenanceTimer.Tick += async (s, e) => await RunMaintenanceAsync();
