            {
                var box = new System.Windows.Controls.CheckBox
                {
                    Content = item,
                    Foreground = System.Windows.Media.Brushes.White,
                    Margin = new Thickness(0, 0, 0, 8),
                    IsChecked = preselected != null && preselected.Contains(item)
                };
