        private void RunUploadScript()
        {
            string? folder = AppContext.BaseDirectory;
            for (int i = 0; i < 9 && !string.IsNullOrEmpty(folder); i++)
            {
                string script = System.IO.Path.Combine(folder, "Hochladen.cmd");
                if (File.Exists(script))
