            Msg("Die Datei „Hochladen.cmd“ wurde nicht gefunden. Lege sie in den Hauptordner deines Projekts (neben die .sln-Datei).", "Hochladen", MessageBoxButton.OK, MessageBoxImage.Information);
        }

