        // ───────────────────────────── Controller: WinMM-Geräte im eigenen Thread, Latenzmessung ─────────────────────────────

        private string padThreadDescription = string.Empty;
        private int padThreadKind;   // 0 = keiner, 1 = Xbox (XInput), 2 = anderes Gamepad (WinMM)
        private double padLatencyMax, padLatencySum;
        private int padLatencyCount, padLatencySpikes;

        private bool TryReadWinMm(uint id, out PadButton mapped)
        {
            mapped = PadButton.None;

            var info = new NativePad.JoyInfoEx
            {
                dwSize = (uint)Interop.Marshal.SizeOf<NativePad.JoyInfoEx>(),
                dwFlags = 0xFF
            };

            uint result;
            try { result = NativePad.joyGetPosEx(id, ref info); }
            catch { return false; }
            if (result != 0) return false;

            mapped = MapJoystick(info);
            return true;
        }

        private bool PollWinMm(ref uint preferred, out PadButton pad)
        {
            pad = PadButton.None;

            uint count;
            try { count = NativePad.joyGetNumDevs(); }
            catch { return false; }
            if (count == 0) return false;
            if (count > 16) count = 16;

            // Zuerst das zuletzt benutzte Gerät, nur bei Verlust werden alle Nummern durchsucht
            if (preferred < count && TryReadWinMm(preferred, out pad)) return true;

            preferred = uint.MaxValue;
            for (uint id = 0; id < count; id++)
            {
                if (!TryReadWinMm(id, out pad)) continue;

                preferred = id;
                padThreadDescription = DescribeJoystick(id);
                return true;
            }

            padThreadDescription = string.Empty;
            return false;
        }

        private void ShowPadLatency()
        {
            if (padLatencyCount == 0)
            {
                ShowToast("🎮", "Controller-Latenz", "Noch keine Eingaben gemessen. Drücke ein paar Tasten.", 5);
                return;
            }

            ShowToast("🎮", "Controller-Latenz",
                $"Ø {padLatencySum / padLatencyCount:F1} ms, Spitze {padLatencyMax:F1} ms ({padLatencyCount} Eingaben, {padLatencySpikes} über 30 ms)", 8);
            padLatencyMax = 0;
            padLatencySum = 0;
            padLatencyCount = 0;
            padLatencySpikes = 0;
        }

        // ───────────────────────────── Controller-Akku und Kabel-Status ─────────────────────────────

        private int padLastWirelessLevel = -1;

        private string BatteryText(int level) => level switch
        {
            3 => "🔋 " + Loc.T("Akku") + ": " + Loc.T("Voll"),
            2 => "🔋 " + Loc.T("Akku") + ": " + Loc.T("Mittel"),
            1 => "🪫 " + Loc.T("Akku") + ": " + Loc.T("Niedrig"),
            _ => "🪫 " + Loc.T("Akku") + ": " + Loc.T("Leer")
        };

        private static string BatteryColor(int level) => level switch
        {
            3 => "#34D399",
            2 => "#A3E635",
            1 => "#F59E0B",
            _ => "#EF4444"
        };

        private void UpdatePadPill()
        {
            if (padBatteryPill == null || padBatteryText == null) return;

            if (padDescription.Length == 0)
            {
                padBatteryPill.Visibility = Visibility.Collapsed;
                return;
            }

            string text, color;
            if (padBatteryWired)
            {
                text = "🔌 " + Loc.T("Kabelgebunden an");
                if (padLastWirelessLevel >= 0) text += "  ·  " + BatteryText(padLastWirelessLevel) + " (" + Loc.T("zuletzt") + ")";
                color = "#60A5FA";
            }
            else if (padBatteryLevel >= 0)
            {
                text = BatteryText(padBatteryLevel);
                color = BatteryColor(padBatteryLevel);
            }
            else
            {
                text = "🎮 " + Loc.T("Verbunden");
                color = "#9CA3AF";
            }

            if (padBatteryText.Text != text)
            {
                padBatteryText.Text = text;
                padBatteryText.Foreground = MakeBrush(color);
            }
            padBatteryPill.Visibility = Visibility.Visible;
        }

        private void PadThreadLoop()
        {
            int slot = -1;
            uint winmm = uint.MaxValue;
            int kind = 0;
            PadButton last = PadButton.None, stick = PadButton.None;
            var clock = System.Diagnostics.Stopwatch.StartNew();
            long lastScan = -10000;

            void Publish(PadButton pad)
            {
                PadButton pressed = pad & ~last;
                last = pad;
                System.Threading.Volatile.Write(ref padThreadState, (int)pad);
                if (pressed == PadButton.None) return;

                padEdges.Enqueue(((int)pressed, System.Diagnostics.Stopwatch.GetTimestamp()));
                if (System.Threading.Interlocked.Exchange(ref padSignalPending, 1) == 0)
                    padDispatcher?.BeginInvoke(DispatcherPriority.Send, new Action(ProcessPadEdges));
            }

            void Reset()
            {
                slot = -1;
                kind = 0;
                last = stick = PadButton.None;
                System.Threading.Volatile.Write(ref padThreadSlot, -1);
                System.Threading.Volatile.Write(ref padThreadKind, 0);
                System.Threading.Volatile.Write(ref padThreadState, 0);
            }

            while (padThreadRun)
            {
                try
                {
                    if (!settings.ControllerSupport)
                    {
                        Reset();
                        System.Threading.Thread.Sleep(300);
                        continue;
                    }

                    // Xbox-Controller: sehr schnell abfragen
                    if (slot >= 0)
                    {
                        if (NativeFeatures.XInputGetState((uint)slot, out var state) != 0)
                        {
                            Reset();
                            lastScan = -10000;
                            continue;
                        }

                        Publish(RemapPad(MapXInput(state, ref stick)));
                        System.Threading.Thread.Sleep(padFast ? 2 : 8);
                        continue;
                    }

                    // Leere Anschlüsse sind langsam abzufragen: nur etwa einmal pro Sekunde suchen
                    if (clock.ElapsedMilliseconds - lastScan >= 1000)
                    {
                        lastScan = clock.ElapsedMilliseconds;
                        for (uint s = 0; s < 4; s++)
                        {
                            if (NativeFeatures.XInputGetState(s, out _) == 0)
                            {
                                slot = (int)s;
                                break;
                            }
                        }

                        System.Threading.Volatile.Write(ref padThreadScanned, 1);
                        if (slot >= 0)
                        {
                            kind = 1;
                            winmm = uint.MaxValue;
                            last = stick = PadButton.None;
                            System.Threading.Volatile.Write(ref padThreadSlot, slot);
                            System.Threading.Volatile.Write(ref padThreadKind, 1);
                            continue;
                        }
                    }

                    // Andere Gamepads (zum Beispiel PlayStation) über WinMM, ebenfalls im Hintergrund
                    if (System.Threading.Volatile.Read(ref padThreadScanned) == 1 && PollWinMm(ref winmm, out var other))
                    {
                        if (kind != 2)
                        {
                            kind = 2;
                            last = stick = PadButton.None;
                            System.Threading.Volatile.Write(ref padThreadSlot, -1);
                            System.Threading.Volatile.Write(ref padThreadKind, 2);
                        }

                        Publish(RemapPad(other));
                        System.Threading.Thread.Sleep(padFast ? 3 : 10);
                        continue;
                    }

                    if (kind != 0) Reset();
                    System.Threading.Thread.Sleep(120);
                }
                catch (DllNotFoundException)
                {
                    xinputMissing = true;
                    break;
                }
                catch (EntryPointNotFoundException)
                {
                    xinputMissing = true;
                    break;
                }
                catch
                {
                    System.Threading.Thread.Sleep(50);
                }
            }

            padThread = null;
        }

        /// <summary>Tastendrücke kommen sofort aus dem Controller-Thread, ohne auf den nächsten Takt zu warten.</summary>
        private void ProcessPadEdges()
        {
            System.Threading.Interlocked.Exchange(ref padSignalPending, 0);

            PadButton edges = PadButton.None;
            long oldest = long.MaxValue;
            while (padEdges.TryDequeue(out var item))
            {
                edges |= (PadButton)item.Edges;
                if (item.Stamp < oldest) oldest = item.Stamp;
            }
            if (edges == PadButton.None) return;

            double milliseconds = (System.Diagnostics.Stopwatch.GetTimestamp() - oldest) * 1000.0 / System.Diagnostics.Stopwatch.Frequency;
            padLatencySum += milliseconds;
            padLatencyCount++;
            if (milliseconds > padLatencyMax) padLatencyMax = milliseconds;
            if (milliseconds > 30) padLatencySpikes++;

            PadButton pad = (PadButton)System.Threading.Volatile.Read(ref padThreadState);
            ProcessPad(pad | edges, edges);
        }

        private void ControllerTick()
        {
            if (!settings.ControllerSupport) return;
            EnsurePadThread();

            int kind = System.Threading.Volatile.Read(ref padThreadKind);
            if (kind == 0)
            {
                TrackPadConnection(false);
                if (padDescription.Length > 0)
                {
                    padDescription = string.Empty;
                    padSlot = -1;
                    UpdatePadStatus();
                    UpdatePadPill();
                }
                return;
            }

            // Abfrage und Tastendrücke laufen im Hintergrund, hier nur Status, Akku und Gedrückthalten
            PadButton pad = (PadButton)System.Threading.Volatile.Read(ref padThreadState);
            if (kind == 1)
            {
                padSlot = System.Threading.Volatile.Read(ref padThreadSlot);
                padDescription = $"Xbox-Controller (Slot {padSlot + 1})";
            }
            else
            {
                padSlot = -1;
                padDescription = padThreadDescription.Length > 0 ? padThreadDescription : "Gamepad";
            }

            UpdatePadStatus();
            TickPadBattery();
            TrackPadConnection(true);
            if (padLayer != null && padLayer.Visibility == Visibility.Visible) UpdatePadPill();

            ProcessPad(pad, PadButton.None);
        }

        // ═════════════════════════════ OBS-Steuerung (OBS WebSocket v5) ═════════════════════════════

        private enum ObsState { Off, Connecting, Connected, Failed, Lost, Simulated }

        private sealed class ObsStatusSnapshot
        {
            public bool Streaming, Recording, RecordPaused;
            public long StreamMs, RecordMs, Skipped, Total;
        }

        private readonly ObsClient obs = new();
        private readonly SemaphoreSlim obsGate = new(1, 1);
        private readonly DispatcherTimer obsUiTimer = new() { Interval = TimeSpan.FromSeconds(1) };
        private DispatcherTimer? obsGraceTimer;
        private CancellationTokenSource? obsLoopCts;
        private ObsState obsState = ObsState.Off;
        private ObsConnectResult obsLastResult = ObsConnectResult.NotReachable;
        private bool obsSimulated;
        private bool obsStreaming, obsRecording, obsRecordPaused, obsMicMuted;
        private DateTime? obsStreamStart, obsRecordStart;
        private long obsRecordFrozenMs;
        private long obsSkipped, obsTotal;
        private string obsMicInput = string.Empty;
        private string obsCurrentScene = string.Empty;
        private List<string> obsScenes = new();
        private bool obsAutoOn, obsAutoSuppressed;

        private bool ObsActive => obsSimulated || obsState == ObsState.Connected;

        private void InitExtras16()
        {
            obs.EventReceived += (type, data) => Dispatcher.BeginInvoke(new Action(() => HandleObsEvent(type, data)));
            obs.Disconnected += () => Dispatcher.BeginInvoke(new Action(() =>
            {
                if (!obsSimulated && obsState == ObsState.Connected) SetObsState(ObsState.Lost);
            }));

            obsUiTimer.Tick += (s, e) =>
            {
                if (obsSimulated && obsStreaming)
                {
                    // Simulation: Bilder zählen und ab und zu eines verlieren
                    obsTotal += 60;
                    if (random.Next(8) == 0) obsSkipped += random.Next(1, 4);
                }
                UpdateObsTimes();
            };
            Closed += (s, e) =>
            {
                try { obsLoopCts?.Cancel(); } catch { }
                obs.Dispose();
            };

            SetObsState(ObsState.Off);
            RestartObs();
        }

        // ───────── Verbindung im Hintergrund, mit automatischer Wiederverbindung ─────────

        private void RestartObs()
        {
            try { obsLoopCts?.Cancel(); } catch { }
            obsLoopCts = null;
            if (obsSimulated) return;

            if (!settings.ObsEnabled)
            {
                _ = Task.Run(async () =>
                {
                    await obsGate.WaitAsync();
                    try { await obs.DisconnectAsync(); } finally { obsGate.Release(); }
                });
                ClearObsData();
                SetObsState(ObsState.Off);
                return;
            }

            var cts = new CancellationTokenSource();
            obsLoopCts = cts;
            string host = settings.ObsHost;
            int port = settings.ObsPort;
            string password = SecretStore.Unprotect(settings.ObsPasswordProtected);
            _ = Task.Run(() => ObsLoopAsync(host, port, password, cts.Token));
        }

        private void ObsUi(Action action) => Dispatcher.BeginInvoke(action);

        private async Task ObsLoopAsync(string host, int port, string password, CancellationToken token)
        {
            // Nur eine Schleife gleichzeitig: Die alte gibt die Verbindung frei, bevor die neue verbindet
            try { await obsGate.WaitAsync(token); }
            catch { return; }

            try
            {
                int delay = 3;
                while (!token.IsCancellationRequested)
                {
                    ObsUi(() => { if (!obsSimulated && obsState != ObsState.Lost) SetObsState(ObsState.Connecting); });

                    var result = await obs.ConnectAsync(host, port, password, token);
                    if (token.IsCancellationRequested) break;

                    if (result == ObsConnectResult.Connected)
                    {
                        delay = 3;
                        await ObsRefreshAllAsync();
                        ObsUi(() => { if (!obsSimulated) SetObsState(ObsState.Connected); });

                        // Status alle 2 Sekunden abfragen (Dauer, verlorene Bilder); Zustandswechsel kommen sofort als Ereignis
                        while (!token.IsCancellationRequested && obs.IsConnected)
                        {
                            try { await Task.Delay(2000, token); } catch { break; }
                            var status = await ObsReadStatusAsync();
                            if (status != null) ObsUi(() => ApplyObsStatus(status));
                        }
                        if (token.IsCancellationRequested) break;
                        ObsUi(() => { if (!obsSimulated) SetObsState(ObsState.Lost); });
                    }
                    else
                    {
                        var failed = result;
                        ObsUi(() =>
                        {
                            obsLastResult = failed;
                            if (!obsSimulated && obsState != ObsState.Lost) SetObsState(ObsState.Failed);
                        });
                        // Bei falschem Passwort seltener versuchen, damit OBS nicht dauernd Anmeldefehler meldet
                        if (failed is ObsConnectResult.AuthFailed or ObsConnectResult.PasswordRequired) delay = 60;
                    }

                    try { await Task.Delay(TimeSpan.FromSeconds(delay), token); } catch { break; }
                    delay = Math.Min(delay * 2, 30);
                }
            }
            catch { }
            finally
            {
                try { await obs.DisconnectAsync(); } catch { }
                obsGate.Release();
            }
        }

        private static string ObsStr(JsonElement? element, string name)
            => element is { ValueKind: JsonValueKind.Object } e && e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String
                ? v.GetString() ?? string.Empty : string.Empty;

        private static bool ObsBool(JsonElement? element, string name)
            => element is { ValueKind: JsonValueKind.Object } e && e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.True;

        private static long ObsLong(JsonElement? element, string name)
            => element is { ValueKind: JsonValueKind.Object } e && e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number
                ? (long)v.GetDouble() : 0;

        private async Task<ObsStatusSnapshot?> ObsReadStatusAsync()
        {
            var stream = await obs.RequestAsync("GetStreamStatus");
            var record = await obs.RequestAsync("GetRecordStatus");
            if (stream == null && record == null) return null;

            return new ObsStatusSnapshot
            {
                Streaming = ObsBool(stream, "outputActive"),
                StreamMs = ObsLong(stream, "outputDuration"),
                Skipped = ObsLong(stream, "outputSkippedFrames"),
                Total = ObsLong(stream, "outputTotalFrames"),
                Recording = ObsBool(record, "outputActive"),
                RecordPaused = ObsBool(record, "outputPaused"),
                RecordMs = ObsLong(record, "outputDuration")
            };
        }

        /// <summary>Lädt Szenen, Mikrofon und Status neu (im Hintergrund) und überträgt alles auf die Oberfläche.</summary>
        private async Task ObsRefreshAllAsync()
        {
            var sceneData = await obs.RequestAsync("GetSceneList");
            var scenes = new List<(long Index, string Name)>();
            if (sceneData is { ValueKind: JsonValueKind.Object } sd && sd.TryGetProperty("scenes", out var list) && list.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in list.EnumerateArray())
                {
                    string name = ObsStr(item, "sceneName");
                    if (name.Length > 0) scenes.Add((ObsLong(item, "sceneIndex"), name));
                }
            }
            string current = ObsStr(sceneData, "currentProgramSceneName");

            var special = await obs.RequestAsync("GetSpecialInputs");
            string mic = ObsStr(special, "mic1");
            bool muted = false;
            if (mic.Length > 0) muted = ObsBool(await obs.RequestAsync("GetInputMute", new { inputName = mic }), "inputMuted");

            var status = await ObsReadStatusAsync();

            ObsUi(() =>
            {
                // OBS liefert die unterste Szene zuerst; wie in OBS von oben nach unten anzeigen
                obsScenes = scenes.OrderByDescending(s => s.Index).Select(s => s.Name).ToList();
                obsCurrentScene = current;
                obsMicInput = mic;
                obsMicMuted = muted;
                if (status != null) ApplyObsStatus(status);
                RenderObs();
                RenderObsSceneAutoList();
                UpdateObsAutoStreamer();
            });
        }

        private void ApplyObsStatus(ObsStatusSnapshot status)
        {
            if (obsSimulated) return;

            obsStreaming = status.Streaming;
            obsRecording = status.Recording;
            obsRecordPaused = status.RecordPaused;
            obsSkipped = status.Skipped;
            obsTotal = status.Total;

            // Startzeit aus der Dauer zurückrechnen, nur bei spürbarer Abweichung nachstellen (sonst springt die Anzeige)
            DateTime now = DateTime.Now;
            if (obsStreaming)
            {
                var start = now - TimeSpan.FromMilliseconds(status.StreamMs);
                if (obsStreamStart == null || Math.Abs((obsStreamStart.Value - start).TotalSeconds) > 2) obsStreamStart = start;
            }
            else obsStreamStart = null;

            obsRecordFrozenMs = status.RecordMs;
            if (obsRecording)
            {
                var start = now - TimeSpan.FromMilliseconds(status.RecordMs);
                if (obsRecordStart == null || Math.Abs((obsRecordStart.Value - start).TotalSeconds) > 2) obsRecordStart = start;
            }
            else obsRecordStart = null;

            RenderObs();
            UpdateObsAutoStreamer();
        }

        private void HandleObsEvent(string type, JsonElement data)
        {
            if (obsSimulated) return;

            switch (type)
            {
                case "StreamStateChanged":
                    obsStreaming = ObsBool(data, "outputActive");
                    if (obsStreaming) obsStreamStart ??= DateTime.Now;
                    else
                    {
                        obsStreamStart = null;
                        obsSkipped = obsTotal = 0;
                    }
                    break;
                case "RecordStateChanged":
                    string state = ObsStr(data, "outputState");
                    obsRecording = ObsBool(data, "outputActive");
                    bool pausedNow = state == "OBS_WEBSOCKET_OUTPUT_PAUSED";
                    if (pausedNow && !obsRecordPaused && obsRecordStart is DateTime pausedFrom)
                        obsRecordFrozenMs = (long)(DateTime.Now - pausedFrom).TotalMilliseconds;
                    if (!pausedNow && obsRecordPaused)
                        obsRecordStart = DateTime.Now - TimeSpan.FromMilliseconds(obsRecordFrozenMs);   // nach der Pause weiterzählen
                    obsRecordPaused = pausedNow;
                    if (obsRecording) obsRecordStart ??= DateTime.Now;
                    else obsRecordStart = null;
                    break;
                case "CurrentProgramSceneChanged":
                    obsCurrentScene = ObsStr(data, "sceneName");
                    break;
                case "SceneListChanged":
                case "SceneCreated":
                case "SceneRemoved":
                case "SceneNameChanged":
                    _ = Task.Run(ObsRefreshAllAsync);
                    return;
                case "InputMuteStateChanged":
                    if (ObsStr(data, "inputName") == obsMicInput) obsMicMuted = ObsBool(data, "inputMuted");
                    break;
                default:
                    return;
            }

            RenderObs();
            UpdateObsAutoStreamer();
        }

        private void ClearObsData()
        {
            obsStreaming = obsRecording = obsRecordPaused = obsMicMuted = false;
            obsStreamStart = obsRecordStart = null;
            obsSkipped = obsTotal = 0;
            obsMicInput = string.Empty;
            obsCurrentScene = string.Empty;
            obsScenes = new List<string>();
            UpdateObsAutoStreamer();
        }

        private void SetObsState(ObsState state)
        {
            obsState = state;

            obsGraceTimer?.Stop();
            if (state == ObsState.Lost)
            {
                // Kurz abgerissen: Zustand (und damit den Streamer-Modus) 30 Sekunden halten, falls OBS gleich wieder da ist
                obsGraceTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(30) };
                obsGraceTimer.Tick += (s, e) =>
                {
                    obsGraceTimer?.Stop();
                    if (obsState == ObsState.Lost && !obsSimulated)
                    {
                        obsLastResult = ObsConnectResult.NotReachable;
                        SetObsState(settings.ObsEnabled ? ObsState.Failed : ObsState.Off);
                    }
                };
                obsGraceTimer.Start();
            }
            else if (state is ObsState.Off or ObsState.Failed)
            {
                ClearObsData();
            }

            RenderObs();
        }

        // ───────── Anzeige ─────────

        private void RenderObs()
        {
            if (ObsCard == null) return;

            bool active = ObsActive;
            string dot, status, hint;
            switch (obsSimulated ? ObsState.Simulated : obsState)
            {
                case ObsState.Simulated:
                    dot = "#A78BFA"; status = "Simulation"; hint = "Testmodus ohne OBS. Alle Knöpfe wirken nur im Launcher.";
                    break;
                case ObsState.Connected:
                    dot = "#34D399"; status = "Verbunden"; hint = string.Empty;
                    break;
                case ObsState.Connecting:
                    dot = "#F59E0B"; status = "Verbinde …"; hint = "Der Launcher verbindet sich mit OBS.";
                    break;
                case ObsState.Lost:
                    dot = "#F59E0B"; status = "Verbindung unterbrochen"; hint = "Die Verbindung zu OBS ist abgerissen. Der Launcher verbindet sich automatisch neu.";
                    break;
                case ObsState.Failed:
                    dot = "#EF4444"; status = "Nicht verbunden"; hint = ObsResultText(obsLastResult) + " " + Loc.T("Der Launcher versucht es automatisch weiter.");
                    break;
                default:
                    dot = "#6B7280"; status = "Aus";
                    hint = "Steuere Szenen, Stream und Aufnahme direkt von hier. Richte die Verbindung unter Einstellungen → Streamer → OBS-Steuerung ein.";
                    break;
            }

            ObsStatusDot.Fill = MakeBrush(dot);
            TxtObsStatus.Text = Loc.T(status);
            TxtObsHint.Text = Loc.T(hint);
            TxtObsHint.Visibility = hint.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
            ObsOfflineButtons.Visibility = active ? Visibility.Collapsed : Visibility.Visible;
            BtnObsConnect.Visibility = settings.ObsEnabled ? Visibility.Visible : Visibility.Collapsed;
            ObsControls.Visibility = active ? Visibility.Visible : Visibility.Collapsed;

            if (active)
            {
                BtnObsStream.Content = Loc.T(obsStreaming ? "Stream beenden" : "Stream starten");
                BtnObsStream.Background = MakeBrush(obsStreaming ? "#DC2626" : "#374151");
                BtnObsRecord.Content = Loc.T(obsRecording ? "Aufnahme beenden" : "Aufnahme starten");
                BtnObsRecord.Background = MakeBrush(obsRecording ? "#DC2626" : "#374151");

                BtnObsMic.IsEnabled = obsMicInput.Length > 0;
                BtnObsMic.Content = Loc.T(obsMicInput.Length == 0 ? "🎙 Kein Mikrofon" : obsMicMuted ? "🔇 Mikrofon stumm" : "🎙 Mikrofon an");
                BtnObsMic.Background = MakeBrush(obsMicMuted ? "#B45309" : "#374151");
                BtnObsMic.ToolTip = obsMicInput.Length == 0
                    ? Loc.T("In OBS ist unter Einstellungen → Audio kein Mikrofon eingerichtet.")
                    : Loc.T("Schaltet das Mikrofon in OBS stumm oder wieder an.");

                RenderObsScenes();
            }

            UpdateObsTimes();
            bool ticking = active && (obsStreaming || obsRecording);
            if (ticking && !obsUiTimer.IsEnabled) obsUiTimer.Start();
            else if (!ticking && obsUiTimer.IsEnabled) obsUiTimer.Stop();
        }

        private static string FormatObsDuration(TimeSpan span)
            => $"{(int)span.TotalHours:00}:{span.Minutes:00}:{span.Seconds:00}";

        private void UpdateObsTimes()
        {
            if (TxtObsLive == null) return;

            TxtObsLive.Text = obsStreaming && obsStreamStart is DateTime start
                ? Loc.T($"Live seit {start:HH:mm} ({FormatObsDuration(DateTime.Now - start)})")
                : Loc.T("Offline");
            TxtObsLive.Foreground = MakeBrush(obsStreaming ? "#F87171" : "#FFFFFF");

            if (obsRecording && obsRecordStart is DateTime recStart)
            {
                // Während einer Pause bleibt die Zeit stehen
                if (obsRecordPaused)
                    TxtObsRecTime.Text = Loc.T($"{FormatObsDuration(TimeSpan.FromMilliseconds(obsRecordFrozenMs))} (pausiert)");
                else
                    TxtObsRecTime.Text = FormatObsDuration(DateTime.Now - recStart);
            }
            else TxtObsRecTime.Text = Loc.T("Aus");

            if (obsStreaming && obsTotal > 0)
            {
                double percent = obsSkipped * 100.0 / obsTotal;
                TxtObsDropped.Text = Loc.T(string.Format(Loc.Culture, "{0} von {1} ({2:0.0} %)", obsSkipped, obsTotal, percent));
                TxtObsDropped.Foreground = MakeBrush(percent >= 5 ? "#F87171" : percent >= 1 ? "#F59E0B" : "#FFFFFF");
            }
            else
            {
                TxtObsDropped.Text = "–";
                TxtObsDropped.Foreground = MakeBrush("#FFFFFF");
            }
        }

        private void RenderObsScenes()
        {
            ObsScenePanel.Children.Clear();
            if (obsScenes.Count == 0)
            {
                ObsScenePanel.Children.Add(new TextBlock { Text = Loc.T("Keine Szenen gefunden."), Foreground = BrushSubtle, FontSize = 12 });
                return;
            }

            foreach (string scene in obsScenes)
            {
                string target = scene;
                bool current = scene == obsCurrentScene;
                var button = new System.Windows.Controls.Button
                {
                    Content = scene,
                    Margin = new Thickness(0, 0, 8, 8),
                    Padding = new Thickness(16, 8, 16, 8),
                    ToolTip = current ? Loc.T("Aktuelle Szene") : Loc.T("Zu dieser Szene wechseln")
                };
                if (current) button.SetResourceReference(System.Windows.Controls.Control.BackgroundProperty, "AccentBrush");
                button.Click += (s, e) => _ = ObsSetSceneAsync(target);
                ObsScenePanel.Children.Add(button);
            }
        }

        // ───────── Befehle (gehen bei der Simulation nicht an OBS) ─────────

        private async Task ObsCommandAsync(string requestType, object? data = null)
        {
            if (obsSimulated)
            {
                SimulateObsCommand(requestType, data);
                return;
            }
            if (obsState != ObsState.Connected) return;

            var result = await Task.Run(() => obs.RequestAsync(requestType, data));
            if (result == null)
                ShowToast("🎥", "OBS", Loc.T("OBS hat den Befehl nicht ausgeführt."), 5);

            // Zustand gleich nachladen, damit die Knöpfe sofort stimmen
            var status = await Task.Run(ObsReadStatusAsync);
            if (status != null) ApplyObsStatus(status);
        }

        private async Task ObsSetSceneAsync(string scene)
        {
            if (!ObsActive) return;
            await ObsCommandAsync("SetCurrentProgramScene", new { sceneName = scene });
            if (!obsSimulated && obsState == ObsState.Connected)
            {
                obsCurrentScene = scene;
                RenderObs();
                UpdateObsAutoStreamer();
            }
        }

        private async Task ObsToggleStreamAsync()
        {
            if (!ObsActive) return;
            if (obsStreaming)
            {
                if (Msg("Stream wirklich beenden?", "OBS", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;
                await ObsCommandAsync("StopStream");
            }
            else await ObsCommandAsync("StartStream");
        }

        private async Task ObsToggleRecordAsync()
        {
            if (!ObsActive) return;
            if (obsRecording)
            {
                if (Msg("Aufnahme wirklich beenden?", "OBS", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;
                await ObsCommandAsync("StopRecord");
            }
            else await ObsCommandAsync("StartRecord");
        }

        private async Task ObsToggleMicAsync()
        {
            if (!ObsActive || obsMicInput.Length == 0) return;
            bool mute = !obsMicMuted;
            await ObsCommandAsync("SetInputMute", new { inputName = obsMicInput, inputMuted = mute });
            if (!obsSimulated) obsMicMuted = mute;
            RenderObs();
        }

        private void BtnObsStream_Click(object sender, RoutedEventArgs e) => _ = ObsToggleStreamAsync();
        private void BtnObsRecord_Click(object sender, RoutedEventArgs e) => _ = ObsToggleRecordAsync();
        private void BtnObsMic_Click(object sender, RoutedEventArgs e) => _ = ObsToggleMicAsync();

        private void BtnObsConnect_Click(object sender, RoutedEventArgs e)
        {
            if (!settings.ObsEnabled) return;
            RestartObs();
        }

        private void BtnObsSettings_Click(object sender, RoutedEventArgs e) => OpenObsSettings();

        private void OpenObsSettings()
        {
            NavigateTo("settings");
            ChipCatStreamer.IsChecked = true;
            Dispatcher.BeginInvoke(new Action(() => ObsSettingsCard.BringIntoView()), DispatcherPriority.Background);
        }

        // ───────── Streamer-Modus automatisch mit Stream und Szenen ─────────

        private void UpdateObsAutoStreamer()
        {
            bool sceneMatch = ObsActive && obsCurrentScene.Length > 0 && settings.ObsStreamerScenes.Contains(obsCurrentScene);
            bool want = (settings.ObsAutoStreamer && obsStreaming) || sceneMatch;

            if (!want)
            {
                obsAutoSuppressed = false;
                if (obsAutoOn)
                {
                    obsAutoOn = false;
                    ApplyStreamerMode();
                    if (!StreamerOn) ShowToast("📡", "Streamer-Modus aus", "OBS sendet nicht mehr. Alle Angaben sind wieder sichtbar.", 5);
                    RenderStreamerPageIfVisible();
                }
                return;
            }

            if (obsAutoOn || obsAutoSuppressed) return;
            obsAutoOn = true;
            if (!settings.StreamerMode && !streamAutoOn)
                ShowToast("📡", "Streamer-Modus aktiv", obsStreaming ? "Dein Stream läuft. Private Angaben sind verborgen." : "Diese OBS-Szene ist für den Streamer-Modus markiert. Private Angaben sind verborgen.", 6);
            ApplyStreamerMode();
            RenderStreamerPageIfVisible();
        }

        private void RenderStreamerPageIfVisible()
        {
            if (ViewStreamer.Visibility == Visibility.Visible) RenderStreamerPage();
        }

        // ───────── Einstellungen ─────────

        private void PopulateObsSettings()
        {
            TxtObsHost.Text = settings.ObsHost;
            TxtObsPort.Text = settings.ObsPort.ToString(CultureInfo.InvariantCulture);
            PwdObs.Password = SecretStore.Unprotect(settings.ObsPasswordProtected);
            ChkObsEnabled.IsChecked = settings.ObsEnabled;
            ChkObsAutoStreamer.IsChecked = settings.ObsAutoStreamer;
            RenderObsSceneAutoList();
        }

        /// <summary>Übernimmt Adresse, Port und Passwort aus den Feldern. Gibt true zurück, wenn sich etwas geändert hat.</summary>
        private bool ReadObsConnectionFields()
        {
            bool changed = false;

            string host = TxtObsHost.Text.Trim();
            if (host.Length == 0) host = "localhost";
            if (host != settings.ObsHost) { settings.ObsHost = host; changed = true; }
            TxtObsHost.Text = host;

            if (int.TryParse(TxtObsPort.Text.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int port) && port is >= 1 and <= 65535)
            {
                if (port != settings.ObsPort) { settings.ObsPort = port; changed = true; }
            }
            TxtObsPort.Text = settings.ObsPort.ToString(CultureInfo.InvariantCulture);

            string password = PwdObs.Password;
            if (password != SecretStore.Unprotect(settings.ObsPasswordProtected))
            {
                settings.ObsPasswordProtected = SecretStore.Protect(password);
                changed = true;
            }

            if (changed) SaveSettings();
            return changed;
        }

        private void ChkObsEnabled_Changed(object sender, RoutedEventArgs e)
        {
            if (isLoadingSettings) return;
            ReadObsConnectionFields();
            settings.ObsEnabled = ChkObsEnabled.IsChecked == true;
            SaveSettings();
            RestartObs();
        }

        private void ChkObsAutoStreamer_Changed(object sender, RoutedEventArgs e)
        {
            if (isLoadingSettings) return;
            settings.ObsAutoStreamer = ChkObsAutoStreamer.IsChecked == true;
            SaveSettings();
            UpdateObsAutoStreamer();
        }

        private void ObsConnectionField_LostFocus(object sender, RoutedEventArgs e)
        {
            if (isLoadingSettings) return;
            if (ReadObsConnectionFields() && settings.ObsEnabled) RestartObs();
        }

        private static string ObsResultText(ObsConnectResult result) => Loc.T(result switch
        {
            ObsConnectResult.NotReachable => "OBS antwortet nicht. Läuft OBS, und ist der WebSocket-Server eingeschaltet (Werkzeuge → WebSocket-Servereinstellungen)? Stimmen Adresse und Port?",
            ObsConnectResult.PasswordRequired => "OBS verlangt ein Passwort. Trage es in den Einstellungen ein.",
            ObsConnectResult.AuthFailed => "Das Passwort für OBS ist falsch.",
            _ => "Die Verbindung zu OBS ist fehlgeschlagen."
        });

        private async void BtnObsTest_Click(object sender, RoutedEventArgs e)
        {
            bool changed = ReadObsConnectionFields();
            string host = settings.ObsHost;
            int port = settings.ObsPort;
            string password = SecretStore.Unprotect(settings.ObsPasswordProtected);

            BtnObsTest.IsEnabled = false;
            TxtObsTestResult.Foreground = MakeBrush("#9CA3AF");
            TxtObsTestResult.Text = Loc.T("Teste die Verbindung …");

            // Eigener Test-Client, damit die laufende Verbindung nicht gestört wird
            var (result, version) = await Task.Run(async () =>
            {
                using var test = new ObsClient();
                using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
                var r = await test.ConnectAsync(host, port, password, cts.Token);
                string v = string.Empty;
                if (r == ObsConnectResult.Connected)
                {
                    v = ObsStr(await test.RequestAsync("GetVersion"), "obsVersion");
                    await test.DisconnectAsync();
                }
                return (r, v);
            });

            BtnObsTest.IsEnabled = true;
            if (result == ObsConnectResult.Connected)
            {
                TxtObsTestResult.Foreground = MakeBrush("#34D399");
                TxtObsTestResult.Text = Loc.T($"✓ Verbindung klappt: OBS {(version.Length > 0 ? version : "?")}")
                    + (settings.ObsEnabled ? string.Empty : " " + Loc.T("Schalte oben „OBS aus dem Launcher steuern“ ein, um OBS von der Streamer-Seite zu bedienen."));
                if (settings.ObsEnabled && (changed || obsState != ObsState.Connected)) RestartObs();
            }
            else
            {
                TxtObsTestResult.Foreground = MakeBrush("#F87171");
                TxtObsTestResult.Text = "✗ " + ObsResultText(result);
            }
        }

        private void RenderObsSceneAutoList()
        {
            if (ObsSceneAutoPanel == null) return;
            ObsSceneAutoPanel.Children.Clear();

            var names = obsScenes.Concat(settings.ObsStreamerScenes).Distinct().ToList();
            foreach (string scene in names)
            {
                string target = scene;
                var box = new System.Windows.Controls.CheckBox
                {
                    Content = scene,
                    IsChecked = settings.ObsStreamerScenes.Contains(scene),
                    Margin = new Thickness(0, 0, 20, 10)
                };
                box.Checked += (s, e) => SetObsStreamerScene(target, true);
                box.Unchecked += (s, e) => SetObsStreamerScene(target, false);
                ObsSceneAutoPanel.Children.Add(box);
            }

            TxtObsSceneAutoHint.Text = obsScenes.Count == 0
                ? Loc.T("Sobald OBS verbunden ist, erscheinen hier deine Szenen zum Auswählen.")
                : string.Empty;
            TxtObsSceneAutoHint.Visibility = obsScenes.Count == 0 ? Visibility.Visible : Visibility.Collapsed;
        }

        private void SetObsStreamerScene(string scene, bool on)
        {
            settings.ObsStreamerScenes.Remove(scene);
            if (on) settings.ObsStreamerScenes.Add(scene);
            SaveSettings();
            UpdateObsAutoStreamer();
        }

        // ───────── Simulation für den Entwickler-Reiter (ohne OBS) ─────────

        private void StartObsSimulation()
        {
            try { obsLoopCts?.Cancel(); } catch { }
            obsLoopCts = null;
            obsSimulated = true;
            obsScenes = new List<string> { "Startet gleich", "Gameplay", "Desktop", "Pause" };
            obsCurrentScene = "Startet gleich";
            obsMicInput = "Mikrofon/AUX";
            obsMicMuted = false;
            obsStreaming = obsRecording = obsRecordPaused = false;
            obsStreamStart = obsRecordStart = null;
            obsSkipped = obsTotal = 0;
            RenderObs();
            RenderObsSceneAutoList();
            UpdateObsAutoStreamer();
            ShowToast("🎥", "OBS", Loc.T("OBS-Simulation gestartet."), 4);
        }

        private void StopObsSimulation()
        {
            if (!obsSimulated) return;
            obsSimulated = false;
            ClearObsData();
            SetObsState(ObsState.Off);
            RenderObsSceneAutoList();
            RestartObs();
        }

        private void HandleObsPauseSimulation()
        {
            if (!obsSimulated || !obsRecording || obsRecordStart is not DateTime start) return;

            if (!obsRecordPaused)
                obsRecordFrozenMs = (long)(DateTime.Now - start).TotalMilliseconds;
            else
                obsRecordStart = DateTime.Now - TimeSpan.FromMilliseconds(obsRecordFrozenMs);
            obsRecordPaused = !obsRecordPaused;
            RenderObs();
        }

        private void SimulateObsCommand(string requestType, object? data)
        {
            string Prop(string name) => data?.GetType().GetProperty(name)?.GetValue(data)?.ToString() ?? string.Empty;

            switch (requestType)
            {
                case "StartStream": obsStreaming = true; obsStreamStart = DateTime.Now; obsSkipped = 0; obsTotal = 1; break;
                case "StopStream": obsStreaming = false; obsStreamStart = null; obsSkipped = obsTotal = 0; break;
                case "StartRecord": obsRecording = true; obsRecordPaused = false; obsRecordStart = DateTime.Now; break;
                case "StopRecord": obsRecording = false; obsRecordPaused = false; obsRecordStart = null; break;
                case "SetInputMute": obsMicMuted = Prop("inputMuted") == bool.TrueString; break;
                case "SetCurrentProgramScene": obsCurrentScene = Prop("sceneName"); break;
            }

            RenderObs();
            UpdateObsAutoStreamer();
        }

        // ═════════════════════════════ Einstellungs-Profile ═════════════════════════════

        /// <summary>Bereiche, die ein Profil umschalten kann, mit den zugehörigen Einstellungen.</summary>
        private static readonly (string Key, string Title, string[] Props)[] ProfileGroups =
        {
            ("design", "Farben und Design", new[] { "BackgroundColor", "AccentColor", "SidebarColor", "NavTextColor", "NavActiveColor", "GlassEffect",
                "AnimatedBackground", "OledMode", "RgbAccent", "RgbSpeed", "UiScale", "CardWidth", "CardCorner", "CardSpacing", "CardAspect",
                "CardLayout", "LibraryView", "HoverZoom", "HoverGlow" }),
            ("background", "Hintergrund", new[] { "BackgroundImagePath", "BgDim", "BgBlur" }),
            ("streamer", "Streamer-Modus", new[] { "StreamerMode", "StreamerAuto", "StreamHideName", "StreamHideLocation", "StreamHideStats",
                "StreamHideRecent", "StreamHidePaths", "StreamHideShots", "StreamHidePc", "StreamHideMusic", "StreamMuteAlerts", "StreamCensorStyle", "ObsAutoStreamer" }),
            ("power", "Energieplan", Array.Empty<string>()),
            ("sidebar", "Seitenleisten-Bereiche", new[] { "HiddenSections", "SidebarCollapsed" }),
            ("controller", "Controller-Optionen", new[] { "ControllerSupport", "ControllerLayout", "PadCombo", "PadComboMode", "PadComboInGame",
                "PadVibrate", "PadRepeat", "PadAutoStart" })
        };

        private static readonly string[] ProfileIcons = { "🎮", "📡", "💼", "🌙", "🎧", "⭐", "🏆", "🛋" };
        private static readonly string[] ObsProcessNames = { "obs64", "obs32", "obs" };

        private sealed class ProfileRestorePoint
        {
            public Dictionary<string, JsonElement> Values = new();
            public string PowerPlan = string.Empty;
            public string ActiveId = string.Empty;
        }

        private ProfileRestorePoint? gameRestore, obsRestore;
        private readonly DispatcherTimer profileObsTimer = new() { Interval = TimeSpan.FromSeconds(5) };
        private bool obsProcessRunning;
        private Forms.ToolStripMenuItem? trayProfilesItem;

        private void InitExtras17()
        {
            SeedProfiles();
            RenderProfiles();

            profileObsTimer.Tick += async (s, e) => await CheckObsProcessForProfileAsync();
            profileObsTimer.Start();
        }

        private void SeedProfiles()
        {
            if (settings.ProfilesSeeded) return;
            settings.ProfilesSeeded = true;

            // Drei Vorschläge: Sie schalten nur den Streamer-Modus und den Energieplan. Mit „Aktuellen Stand speichern“ kommt mehr dazu.
            SettingsProfile Make(string name, string icon, bool streamer, string plan) => new()
            {
                Name = name,
                Icon = icon,
                Groups = new List<string> { "streamer", "power" },
                Values = new Dictionary<string, JsonElement> { ["StreamerMode"] = JsonSerializer.SerializeToElement(streamer) },
                PowerPlan = plan
            };

            if (settings.Profiles.Count == 0)
            {
                settings.Profiles.Add(Make("Zocken", "🎮", false, "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"));
                settings.Profiles.Add(Make("Streamen", "📡", true, "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"));
                settings.Profiles.Add(Make("Büro", "💼", false, "381b4222-f694-41f0-9685-ff5bb260df2e"));
            }
            SaveSettings();
        }

        private SettingsProfile? FindProfile(string id)
            => string.IsNullOrEmpty(id) ? null : settings.Profiles.FirstOrDefault(p => p.Id == id);

        // ───────── Werte erfassen und anwenden ─────────

        private Dictionary<string, JsonElement> CaptureProfileValues(IEnumerable<string> groups)
        {
            var values = new Dictionary<string, JsonElement>();
            foreach (var group in ProfileGroups.Where(g => groups.Contains(g.Key)))
            {
                foreach (string name in group.Props)
                {
                    var property = typeof(AppSettings).GetProperty(name);
                    if (property == null) continue;
                    values[name] = JsonSerializer.SerializeToElement(property.GetValue(settings), property.PropertyType);
                }
            }
            return values;
        }

        /// <summary>Setzt die gespeicherten Werte und frischt die Oberfläche auf. Unbekannte Einträge werden übersprungen.</summary>
        private void ApplyProfileValues(Dictionary<string, JsonElement> values)
        {
            bool design = false;
            var designProps = ProfileGroups.First(g => g.Key == "design").Props.Concat(ProfileGroups.First(g => g.Key == "background").Props).ToHashSet();

            foreach (var (name, value) in values)
            {
                var property = typeof(AppSettings).GetProperty(name);
                if (property == null || !property.CanWrite) continue;
                try
                {
                    property.SetValue(settings, value.Deserialize(property.PropertyType));
                    if (designProps.Contains(name)) design = true;
                }
                catch { }
            }

            // Absichern wie beim Laden
            settings.HiddenSections ??= new List<string>();
            settings.BackgroundImagePath ??= string.Empty;
            if (!settings.RgbUnlocked) settings.RgbAccent = false;
            SaveSettings();

            isLoadingSettings = true;
            try { PopulateControlsFromSettings(); }
            finally { isLoadingSettings = false; }

            if (design)
            {
                imageCache.Clear();
                ApplyTheme();
                ApplyBackgroundImage();
                ApplyGlowBackground();
                ApplyViewSettings();
                ApplyFilter();
                ApplyPixelShift();
            }
            ApplySidebar(false);
            ApplyNavVisibility();
            BuildNavSettings();
            ApplyStreamerMode();
            UpdateStreamerToggles();
            RefreshDashboard();
        }

        private static async Task<string> ReadActivePowerPlanAsync()
        {
            var result = await Task.Run(() => RunHidden("powercfg", "/getactivescheme"));
            var match = Regex.Match(result.Output, @"[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}");
            return match.Success ? match.Value : string.Empty;
        }

        private void ApplyProfile(SettingsProfile profile, bool auto)
        {
            ApplyProfileValues(profile.Values);
            if (profile.Groups.Contains("power") && profile.PowerPlan.Length > 0) _ = ActivatePowerPlanAsync(profile.PowerPlan, auto);

            settings.ActiveProfileId = profile.Id;
            SaveSettings();
            RenderProfiles();
            ShowToast(profile.Icon, auto ? "Profil automatisch gewechselt" : "Profil gewechselt", Loc.T($"Profil „{profile.Name}“ ist aktiv."), 4);
        }

        /// <summary>Umschalten von Hand (Einstellungen, Suche, Infobereich). Eine laufende Automatik kehrt danach nicht mehr zurück.</summary>
        private void ActivateProfileManually(SettingsProfile profile)
        {
            gameRestore = null;
            obsRestore = null;
            ApplyProfile(profile, false);
        }

        // ───────── Automatik: Spielstart und OBS ─────────

        private async Task AutoActivateProfileAsync(string profileId, bool forGame)
        {
            var profile = FindProfile(profileId);
            if (profile == null || settings.ActiveProfileId == profile.Id) return;
            if (forGame ? gameRestore != null : obsRestore != null) return;

            // Den jetzigen Stand genau der Bereiche merken, die das Profil ändert
            var point = new ProfileRestorePoint
            {
                Values = CaptureProfileValues(profile.Groups),
                ActiveId = settings.ActiveProfileId
            };
            if (profile.Groups.Contains("power") && profile.PowerPlan.Length > 0) point.PowerPlan = await ReadActivePowerPlanAsync();

            if (forGame) gameRestore = point;
            else obsRestore = point;
            ApplyProfile(profile, true);
        }

        private void AutoRestoreProfile(bool forGame)
        {
            var point = forGame ? gameRestore : obsRestore;
            if (forGame) gameRestore = null;
            else obsRestore = null;
            if (point == null) return;

            ApplyProfileValues(point.Values);
            if (point.PowerPlan.Length > 0) _ = ActivatePowerPlanAsync(point.PowerPlan, true);
            settings.ActiveProfileId = FindProfile(point.ActiveId)?.Id ?? string.Empty;
            SaveSettings();
            RenderProfiles();
            ShowToast("↩", "Profil zurückgesetzt", forGame ? "Das Spiel ist beendet. Deine vorherigen Einstellungen gelten wieder." : "OBS wurde beendet. Deine vorherigen Einstellungen gelten wieder.", 4);
        }

        private void OnProfileGameStarted()
        {
            if (settings.ProfileOnGame.Length > 0) _ = AutoActivateProfileAsync(settings.ProfileOnGame, true);
        }

        private void OnProfileGameEnded()
        {
            if (gameRestore != null) AutoRestoreProfile(true);
        }

        private async Task CheckObsProcessForProfileAsync()
        {
            if (settings.ProfileOnObs.Length == 0 && obsRestore == null)
            {
                obsProcessRunning = false;
                return;
            }

            bool running = await Task.Run(() => ObsProcessNames.Any(IsProcessRunning));
            if (running == obsProcessRunning) return;
            obsProcessRunning = running;

            if (running && settings.ProfileOnObs.Length > 0) await AutoActivateProfileAsync(settings.ProfileOnObs, false);
            else if (!running && obsRestore != null) AutoRestoreProfile(false);
        }

        // ───────── Anzeige in den Einstellungen ─────────

        private string DescribeProfile(SettingsProfile profile)
        {
            var parts = new List<string>();
            foreach (var group in ProfileGroups.Where(g => profile.Groups.Contains(g.Key)))
            {
                if (group.Key == "power")
                {
                    string plan = PowerPlanNames.TryGetValue(profile.PowerPlan, out var name) ? name : string.Empty;
                    parts.Add(plan.Length > 0 ? Loc.T("Energieplan") + ": " + Loc.T(plan) : Loc.T("Energieplan"));
                }
                else if (group.Key == "streamer" && profile.Values.TryGetValue("StreamerMode", out var mode))
                {
                    parts.Add(Loc.T(mode.ValueKind == JsonValueKind.True ? "Streamer-Modus an" : "Streamer-Modus aus"));
                }
                else parts.Add(Loc.T(group.Title));
            }
            return parts.Count == 0 ? Loc.T("Schaltet noch nichts um") : string.Join(" · ", parts);
        }

        private void RenderProfiles()
        {
            if (ProfilesPanel == null) return;
            ProfilesPanel.Children.Clear();

            foreach (var item in settings.Profiles)
            {
                var profile = item;
                bool active = profile.Id == settings.ActiveProfileId;

                var row = new Grid { Margin = new Thickness(0, 0, 0, 10) };
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                row.Children.Add(new TextBlock { Text = profile.Icon, FontSize = 22, Margin = new Thickness(0, 0, 12, 0), VerticalAlignment = System.Windows.VerticalAlignment.Center });

                var texts = new StackPanel { VerticalAlignment = System.Windows.VerticalAlignment.Center, Margin = new Thickness(0, 0, 12, 0) };
                var title = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal };
                title.Children.Add(new TextBlock { Text = profile.Name, Foreground = System.Windows.Media.Brushes.White, FontWeight = FontWeights.SemiBold });
                if (active)
                    title.Children.Add(new TextBlock { Text = Loc.T("aktiv"), Foreground = MakeBrush("#34D399"), FontSize = 11, FontWeight = FontWeights.SemiBold, Margin = new Thickness(8, 1, 0, 0) });
                texts.Children.Add(title);
                texts.Children.Add(new TextBlock { Text = DescribeProfile(profile), Foreground = BrushSubtle, FontSize = 12, TextWrapping = TextWrapping.Wrap });
                Grid.SetColumn(texts, 1);
                row.Children.Add(texts);

                var buttons = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal, VerticalAlignment = System.Windows.VerticalAlignment.Center };
                var use = new System.Windows.Controls.Button { Content = Loc.T("Aktivieren"), Margin = new Thickness(0, 0, 8, 0), Padding = new Thickness(14, 6, 14, 6) };
                if (!active) use.SetResourceReference(System.Windows.Controls.Control.BackgroundProperty, "AccentBrush");
                use.Click += (s, e) => ActivateProfileManually(profile);
                var edit = new System.Windows.Controls.Button { Content = Loc.T("Bearbeiten"), Padding = new Thickness(14, 6, 14, 6) };
                edit.Click += (s, e) => EditProfile(profile);
                buttons.Children.Add(use);
                buttons.Children.Add(edit);
                Grid.SetColumn(buttons, 2);
                row.Children.Add(buttons);

                ProfilesPanel.Children.Add(row);
            }

            if (settings.Profiles.Count == 0)
                ProfilesPanel.Children.Add(new TextBlock { Text = Loc.T("Noch keine Profile angelegt."), Foreground = BrushSubtle, FontSize = 12, Margin = new Thickness(0, 0, 0, 8) });

            RenderProfileAutoChips(ProfileOnGamePanel, settings.ProfileOnGame, id => settings.ProfileOnGame = id);
            RenderProfileAutoChips(ProfileOnObsPanel, settings.ProfileOnObs, id => settings.ProfileOnObs = id);
        }

        private void RenderProfileAutoChips(System.Windows.Controls.WrapPanel panel, string selected, Action<string> set)
        {
            panel.Children.Clear();
            string group = "ProfileAuto" + panel.Name;
            var style = TryFindResource("ChipStyle") as Style;

            void Chip(string text, string id)
            {
                var chip = new System.Windows.Controls.RadioButton { Content = text, GroupName = group, IsChecked = id == selected };
                if (style != null) chip.Style = style;
                chip.Checked += (s, e) =>
                {
                    set(id);
                    SaveSettings();
                };
                panel.Children.Add(chip);
            }

            Chip(Loc.T("Aus"), string.Empty);
            foreach (var profile in settings.Profiles) Chip(profile.Icon + " " + profile.Name, profile.Id);
        }

        // ───────── Anlegen, bearbeiten, löschen ─────────

        private void BtnNewProfile_Click(object sender, RoutedEventArgs e) => EditProfile(null);

        private void EditProfile(SettingsProfile? existing)
        {
            bool isNew = existing == null;
            var dialog = CreateDialog(isNew ? "Neues Profil" : "Profil bearbeiten", 560, out var panel);

            panel.Children.Add(new TextBlock { Text = Loc.T("Name"), Foreground = BrushSubtle, FontSize = 12 });
            var name = new System.Windows.Controls.TextBox { Text = existing?.Name ?? string.Empty, Height = 38, Margin = new Thickness(0, 4, 0, 14) };
            panel.Children.Add(name);

            panel.Children.Add(new TextBlock { Text = Loc.T("Symbol"), Foreground = BrushSubtle, FontSize = 12, Margin = new Thickness(0, 0, 0, 4) });
            var icons = new WrapPanel { Margin = new Thickness(0, 0, 0, 14) };
            string icon = existing?.Icon ?? "⭐";
            var chipStyle = TryFindResource("ChipStyle") as Style;
            foreach (string candidate in ProfileIcons)
            {
                string value = candidate;
                var chip = new System.Windows.Controls.RadioButton { Content = value, GroupName = "ProfileIcon", IsChecked = value == icon, FontSize = 16 };
                if (chipStyle != null) chip.Style = chipStyle;
                chip.Checked += (s, e) => icon = value;
                icons.Children.Add(chip);
            }
            panel.Children.Add(icons);

            panel.Children.Add(new TextBlock { Text = Loc.T("Was das Profil umschaltet"), Foreground = System.Windows.Media.Brushes.White, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 8) });
            var groupBoxes = new Dictionary<string, System.Windows.Controls.CheckBox>();
            var planPanel = new WrapPanel { Margin = new Thickness(56, 0, 0, 10) };
            foreach (var group in ProfileGroups)
            {
                var box = new System.Windows.Controls.CheckBox
                {
                    Content = Loc.T(group.Title),
                    IsChecked = existing == null ? group.Key is "design" or "streamer" : existing.Groups.Contains(group.Key),
                    Margin = new Thickness(0, 0, 0, 8)
                };
                groupBoxes[group.Key] = box;
                panel.Children.Add(box);
                if (group.Key == "power") panel.Children.Add(planPanel);
            }

            // Energieplan: einer der Windows-Standardpläne
            string plan = existing?.PowerPlan ?? string.Empty;
            if (!PowerPlanNames.ContainsKey(plan))
                plan = PowerPlanNames.FirstOrDefault(p => p.Value == currentPowerPlanName).Key ?? "381b4222-f694-41f0-9685-ff5bb260df2e";
            foreach (var (guid, title) in PowerPlanNames)
            {
                string value = guid;
                var chip = new System.Windows.Controls.RadioButton { Content = Loc.T(title), GroupName = "ProfilePlan", IsChecked = value.Equals(plan, StringComparison.OrdinalIgnoreCase) };
                if (chipStyle != null) chip.Style = chipStyle;
                chip.Checked += (s, e) => plan = value;
                planPanel.Children.Add(chip);
            }
            void UpdatePlanVisibility() => planPanel.Visibility = groupBoxes["power"].IsChecked == true ? Visibility.Visible : Visibility.Collapsed;
            groupBoxes["power"].Checked += (s, e) => UpdatePlanVisibility();
            groupBoxes["power"].Unchecked += (s, e) => UpdatePlanVisibility();
            UpdatePlanVisibility();

            System.Windows.Controls.CheckBox? capture = null;
            if (!isNew)
            {
                capture = new System.Windows.Controls.CheckBox { Content = Loc.T("Meine aktuellen Einstellungen in das Profil übernehmen"), Margin = new Thickness(0, 6, 0, 0) };
                panel.Children.Add(capture);
            }
            panel.Children.Add(new TextBlock
            {
                Text = Loc.T(isNew
                    ? "Das Profil merkt sich deine jetzigen Einstellungen für die ausgewählten Bereiche."
                    : "Neu ausgewählte Bereiche übernehmen immer deine jetzigen Einstellungen."),
                Foreground = BrushSubtle,
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 6, 0, 18)
            });

            var buttons = new Grid();
            var right = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal, HorizontalAlignment = System.Windows.HorizontalAlignment.Right };
            var cancel = new System.Windows.Controls.Button { Content = "Abbrechen", Margin = new Thickness(0, 0, 10, 0), IsCancel = true };
            var save = new System.Windows.Controls.Button { Content = "Speichern", Padding = new Thickness(28, 8, 28, 8), IsDefault = true };
            save.SetResourceReference(System.Windows.Controls.Control.BackgroundProperty, "AccentBrush");
            right.Children.Add(cancel);
            right.Children.Add(save);
            buttons.Children.Add(right);

            if (existing != null)
            {
                var delete = new System.Windows.Controls.Button { Content = "Löschen", HorizontalAlignment = System.Windows.HorizontalAlignment.Left, Background = MakeBrush("#7F1D1D") };
                delete.Click += (s, e) =>
                {
                    if (Msg($"Profil „{existing.Name}“ wirklich löschen?", "Profil löschen", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;
                    settings.Profiles.Remove(existing);
                    if (settings.ActiveProfileId == existing.Id) settings.ActiveProfileId = string.Empty;
                    if (settings.ProfileOnGame == existing.Id) settings.ProfileOnGame = string.Empty;
                    if (settings.ProfileOnObs == existing.Id) settings.ProfileOnObs = string.Empty;
                    SaveSettings();
                    dialog.DialogResult = false;
                };
                buttons.Children.Add(delete);
            }
            panel.Children.Add(buttons);

            save.Click += (s, e) =>
            {
                string text = name.Text.Trim();
                if (text.Length == 0)
                {
                    name.Focus();
                    return;
                }

                var groups = ProfileGroups.Select(g => g.Key).Where(k => groupBoxes[k].IsChecked == true).ToList();
                var profile = existing ?? new SettingsProfile();
                var added = groups.Except(profile.Groups).ToList();
                bool takeAll = isNew || capture?.IsChecked == true;

                // Werte: bei „übernehmen“ alles neu erfassen, sonst nur neu hinzugekommene Bereiche; abgewählte Bereiche entfernen
                var values = takeAll ? new Dictionary<string, JsonElement>() : new Dictionary<string, JsonElement>(profile.Values);
                foreach (var (key, value) in CaptureProfileValues(takeAll ? groups : added)) values[key] = value;
                var keep = ProfileGroups.Where(g => groups.Contains(g.Key)).SelectMany(g => g.Props).ToHashSet();
                foreach (string key in values.Keys.Where(k => !keep.Contains(k)).ToList()) values.Remove(key);

                profile.Name = text;
                profile.Icon = icon;
                profile.Groups = groups;
                profile.Values = values;
                profile.PowerPlan = groups.Contains("power") ? plan : string.Empty;
                if (isNew) settings.Profiles.Add(profile);
                SaveSettings();
                dialog.DialogResult = true;
            };

            dialog.Loaded += (s, e) => name.Focus();
            dialog.ShowDialog();
            RenderProfiles();
        }

